#include <chrono>
#include <cmath>
#include <cstdio>
#include <random>

int main() {
    const double S0 = 100.0, K = 100.0, r = 0.05, sigma = 0.2, T = 1.0;
    const int n = 10'000'000;                 // 一千万条路径

    std::mt19937_64 rng(42);
    std::normal_distribution<double> norm(0.0, 1.0);

    const auto t0 = std::chrono::steady_clock::now();
    double sum = 0.0;
    for (int i = 0; i < n; ++i) {
        const double z = norm(rng);
        const double ST = S0 * std::exp((r - 0.5 * sigma * sigma) * T + sigma * std::sqrt(T) * z);
        if (ST > K) sum += ST - K;
    }
    const double price = std::exp(-r * T) * sum / n;
    const double secs = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();

    std::printf("price = %.4f  (%.2f s)\n", price, secs);
    return 0;
}

#include <algorithm>
