int main() {
    const int n = 2'000'000;
    const double S0 = 100.0, K = 100.0, r = 0.05, sigma = 0.2, T = 1.0;
    const double sT = std::sqrt(T), df = std::exp(-r * T);

    std::mt19937_64 rng(42);
    std::normal_distribution<double> norm(0.0, 1.0);

    const auto t0 = std::chrono::steady_clock::now();
    double sum = 0.0;
    for (int i = 0; i < n; ++i)
        sum += std::max(S0 * std::exp((r - 0.5 * sigma * sigma) * T + sigma * sT * norm(rng)) - K, 0.0);
    const double secs = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();

    const double ns_per_path = secs * 1e9 / n;
    const double hours = 2e10 * ns_per_path / 1e9 / 3600.0;   // 10 亿条路径 x 20 个标的

    std::printf("price = %.4f\n", df * sum / n);
    std::printf("%.1f ns/path, %d paths in %.2f s\n", ns_per_path, n, secs);
    std::printf("20 assets, 1e9 paths = %.1f hours\n", hours);
    return 0;
}

#include <cmath>
#include <cstdio>
#include <numbers>

struct BlackScholes {
    double S, K, r, sigma, T;

    static double cdf(double x) {
        return 0.5 * (1.0 + std::erf(x / std::numbers::sqrt2));
    }

    double price() const {
        const double sigT = sigma * std::sqrt(T);
        const double d1 = (std::log(S / K) + (r + 0.5 * sigma * sigma) * T) / sigT;
        const double d2 = d1 - sigT;
        return S * cdf(d1) - K * std::exp(-r * T) * cdf(d2);
    }
};

int main() {
    const BlackScholes bs{100.0, 100.0, 0.05, 0.2, 1.0};
    std::printf("call = %.4f\n", bs.price());
    return 0;
}

#include <cmath>
#include <cstdio>
#include <numbers>
#include <stdexcept>

class BlackScholes {
public:
    BlackScholes(double spot, double strike, double rate, double vol, double maturity)
        : S_(spot), K_(strike), r_(rate), sigma_(vol), T_(maturity) {
        if (S_ <= 0.0 || K_ <= 0.0) throw std::invalid_argument("spot/strike must be > 0");
        if (sigma_ <= 0.0)          throw std::invalid_argument("vol must be > 0");
        if (T_ <= 0.0)              throw std::invalid_argument("maturity must be > 0");
    }

    double price() const {
        return S_ * cdf(d1()) - K_ * std::exp(-r_ * T_) * cdf(d2());
    }

    double delta() const { return cdf(d1()); }      // call 的 delta

private:
    static double cdf(double x) { return 0.5 * (1.0 + std::erf(x / std::numbers::sqrt2)); }

    double d1() const {
        const double sigT = sigma_ * std::sqrt(T_);
        return (std::log(S_ / K_) + (r_ + 0.5 * sigma_ * sigma_) * T_) / sigT;
    }
    double d2() const { return d1() - sigma_ * std::sqrt(T_); }

    double S_, K_, r_, sigma_, T_;
};

int main() {
    const BlackScholes bs(100.0, 100.0, 0.05, 0.2, 1.0);
    std::printf("call  = %.4f\n", bs.price());
    std::printf("delta = %.4f\n", bs.delta());

    try {
        const BlackScholes bad(100.0, 100.0, 0.05, -0.2, 1.0);   // 波动率不能是负的
        std::printf("not reached: %.4f\n", bad.price());
    } catch (const std::exception& e) {
        std::printf("rejected: %s\n", e.what());
    }
    return 0;
}

#include <cmath>
#include <cstdio>
#include <numbers>
#include <stdexcept>

class BlackScholes {
public:
    BlackScholes(double spot, double strike, double rate, double vol, double maturity)
        : S_(spot), K_(strike), r_(rate), sigma_(vol), T_(maturity) {
        if (S_ <= 0.0 || K_ <= 0.0) throw std::invalid_argument("spot/strike must be > 0");
        if (sigma_ <= 0.0)          throw std::invalid_argument("vol must be > 0");
        if (T_ <= 0.0)              throw std::invalid_argument("maturity must be > 0");
    }

    double price() const { return S_ * cdf(d1()) - K_ * std::exp(-r_ * T_) * cdf(d2()); }
    double delta() const { return cdf(d1()); }
    double gamma() const { return pdf(d1()) / (S_ * sigma_ * std::sqrt(T_)); }
    double vega()  const { return S_ * std::sqrt(T_) * pdf(d1()); }

private:
    static double cdf(double x) { return 0.5 * (1.0 + std::erf(x / std::numbers::sqrt2)); }
    static double pdf(double x) { return std::exp(-0.5 * x * x) / std::sqrt(2.0 * std::numbers::pi); }

    double d1() const {
        const double sigT = sigma_ * std::sqrt(T_);
        return (std::log(S_ / K_) + (r_ + 0.5 * sigma_ * sigma_) * T_) / sigT;
    }
    double d2() const { return d1() - sigma_ * std::sqrt(T_); }

    double S_, K_, r_, sigma_, T_;
};

int main() {
    const double S = 100.0, K = 100.0, r = 0.05, T = 1.0;

    std::printf("%6s %9s %8s %8s %8s\n", "vol", "price", "delta", "gamma", "vega");
    for (double vol = 0.10; vol < 0.51; vol += 0.10) {
        const BlackScholes bs(S, K, r, vol, T);
        std::printf("%6.2f %9.4f %8.4f %8.4f %8.2f\n",
                    vol, bs.price(), bs.delta(), bs.gamma(), bs.vega());
    }
    return 0;
}

#include <algorithm>
#include <cstdio>

class Payoff {
public:
    virtual ~Payoff() = default;
    virtual double operator()(double spot) const = 0;
};

class CallPayoff : public Payoff {
public:
    explicit CallPayoff(double strike) : strike_(strike) {}
    double operator()(double spot) const override { return std::max(spot - strike_, 0.0); }
private:
    double strike_;
};

class PutPayoff : public Payoff {
public:
    explicit PutPayoff(double strike) : strike_(strike) {}
    double operator()(double spot) const override { return std::max(strike_ - spot, 0.0); }
private:
    double strike_;
};

int main() {
    const CallPayoff call(100.0);
    const PutPayoff  put(100.0);

    const Payoff* a = &call;      // 基类指针，指向子类对象
    const Payoff* b = &put;
    std::printf("call at 110 = %5.2f\n", (*a)(110.0));
    std::printf("put  at  90 = %5.2f\n", (*b)(90.0));
    return 0;
}

