    double operator()(double spot) const override { return std::max(strike_ - spot, 0.0); }
private:
    double strike_;
};

std::unique_ptr<Payoff> make_payoff(const std::string& kind, double strike) {
    if (kind == "call") return std::make_unique<CallPayoff>(strike);
    if (kind == "put")  return std::make_unique<PutPayoff>(strike);
    return nullptr;                       // 不认识的类型
}

int main() {
    std::vector<std::unique_ptr<Payoff>> book;
    book.push_back(make_payoff("call", 100.0));
    book.push_back(make_payoff("put", 90.0));

    auto unknown = make_payoff("straddle", 100.0);
    if (!unknown) std::printf("rejected: unknown payoff\n");

    std::unique_ptr<Payoff> moved = std::move(book[0]);   // 移交所有权，不是拷贝
    if (!book[0]) std::printf("book[0] is now empty\n");

    std::printf("moved(105)  = %.2f\n", (*moved)(105.0));
    std::printf("book[1](85) = %.2f\n", (*book[1])(85.0));
    return 0;
}

